<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/Admin/Users.php';require dirname(__DIR__).'/app/Mail/InternalMail.php';require dirname(__DIR__).'/app/Mail/Reception.php';require dirname(__DIR__).'/app/UI/Conversation.php';
use TNL\Mail\InternalMail;use TNL\Mail\Reception;use TNL\Mail\ExternalAccount;
function tnl_escape(string $s):string{return htmlspecialchars($s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function chatCheck(bool $ok,string $label):void{if(!$ok)throw new RuntimeException($label);echo "PASS: $label\n";}
$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);\TNL\Admin\Users::init($db);foreach(['alice','bob','carl'] as $name)\TNL\Admin\Users::create($db,['username'=>$name,'display_name'=>ucfirst($name),'domain'=>'example.test','password'=>'test-password-only']);
InternalMail::send($db,2,'alice','Consulta','Mensaje recibido');$first=(int)$db->lastInsertId();InternalMail::send($db,1,'bob','Re: Consulta','Respuesta enviada',$first);$reply=(int)$db->lastInsertId();$db->exec('UPDATE internal_messages SET read_at=NULL WHERE id='.$first);InternalMail::send($db,3,'alice','Consulta','Otro hilo');$list=InternalMail::threads($db,1);chatCheck(count($list)===2,'inbox merges sent and received by reply relation, never by subject');$group=array_values(array_filter($list,fn($m)=>(int)$m['id']===$reply))[0];chatCheck($group['message_count']===2&&$group['unread_count']===1,'thread keeps unread incoming count after outgoing reply');$thread=InternalMail::conversation($db,1,$reply);chatCheck(count($thread)===2,'opening an outgoing reply includes incoming message');chatCheck((int)$db->query('SELECT count(*) FROM internal_messages WHERE recipient_id=1 AND read_at IS NULL')->fetchColumn()===1,'only the opened internal conversation is marked read');chatCheck(InternalMail::conversation($db,3,$reply)===[],'unrelated employee cannot read internal thread');
$storage=sys_get_temp_dir().'/tnl-chat-'.bin2hex(random_bytes(6));mkdir($storage,0700);Reception::init($db);\TNL\Admin\Settings::set($db,'reception_enabled','1');\TNL\Admin\Settings::set($db,'reception_owner','admin:1');$store=new ExternalAccount($db,$storage);$in=['headers'=>['from'=>'client@outside.test','to'=>'alice@example.test','message-id'=>'<in@outside.test>','date'=>'2026-10-17T10:00:00Z'],'body'=>'Primera consulta'];Reception::ingest($db,'admin:1',99,4,$in,$storage);$message=Reception::read($db,1,1);$store->recordSent('admin:1','client@outside.test','Re: Consulta','Nuestra respuesta','<out@example.test>',['in_reply_to'=>'<in@outside.test>','references'=>'<in@outside.test>']);$store->recordSent('admin:2','client@outside.test','Re: Consulta','Secreto','<other@example.test>',['references'=>'<in@outside.test>']);$store->recordSent('admin:1','other@outside.test','Re: Consulta','No relacionado','<unrelated@example.test>');$conversation=Reception::conversation($db,$message,1,false,$storage);chatCheck(count($conversation)===2&&!empty($conversation[1]['outgoing']),'assigned reception contains own mailbox sent copy, excludes other owners and unrelated mail');chatCheck(Reception::conversation($db,$message,2,false,$storage)===[],'other employee cannot view assigned reception');$route=Reception::outbound($db,'admin:1',1,['client@outside.test'],$storage,['in_reply_to'=>'<in@outside.test>']);chatCheck($route['token']===$message['token'],'reply preserves assigned conversation routing token');
ob_start();\TNL\UI\Conversation::render(array_merge($conversation,[$conversation[0]]),false,'<in@outside.test>');$html=ob_get_clean();chatCheck(substr_count($html,'<article class="chat-message')===2,'chat renders current incoming and sent messages once each');chatCheck(str_contains($html,'chat-outgoing')&&str_contains($html,'Nuestra respuesta')&&str_contains($html,'Primera consulta')&&!str_contains($html,'<details>'),'messages are expanded as incoming and outgoing chat bubbles');chatCheck(strpos($html,'Nuestra respuesta')<strpos($html,'Primera consulta'),'chat messages put newest first');

$inbox=$store->inboxThreads('admin:1',['messages'=>[['uid'=>4,'from'=>'client@outside.test','subject'=>'Consulta','date'=>'2026-10-17T10:00:00Z','unread'=>true,'headers'=>['message-id'=>'<in@outside.test>']]]]);chatCheck(count($inbox['messages'])===2,'external conversation list includes sent and received without duplicate rows for a reply');$joined=array_values(array_filter($inbox['messages'],fn($m)=>$m['unread_count']===1));chatCheck(count($joined)===1&&$joined[0]['message_count']===2&&$joined[0]['sent_id']===1,'external thread shows incoming unread count even when latest message was sent');

$many=[];for($i=0;$i<23;$i++)$many[]=['headers'=>['message-id'=>'<page-'.$i.'@example.test>','from'=>'Peer','date'=>gmdate('c',1700000000+$i)],'body'=>'page-message-'.$i.'!'];$_GET=['id'=>'7','thread_page'=>'2'];ob_start();\TNL\UI\Conversation::render($many,false);$paged=ob_get_clean();chatCheck(substr_count($paged,'<article class="chat-message')===10,'conversation pages contain ten messages');chatCheck(strpos($paged,'page-message-12!')<strpos($paged,'page-message-3!')&&!str_contains($paged,'page-message-22!'),'second page is descending and excludes newest page');chatCheck(str_contains($paged,'id=7')&&str_contains($paged,'thread_page=3'),'pagination preserves selected conversation');$_GET=['thread_page'=>'999'];ob_start();\TNL\UI\Conversation::render($many,false);$last=ob_get_clean();chatCheck(substr_count($last,'<article class="chat-message')===3,'out-of-range page is clamped to final page');$_GET=[];

$simultaneous=[['sort_id'=>1,'headers'=>['message-id'=>'<one@same.test>','date'=>'2026-10-17T10:00:00Z'],'body'=>'older-same-second'],['sort_id'=>2,'headers'=>['message-id'=>'<two@same.test>','date'=>'2026-10-17T10:00:00Z'],'body'=>'newer-same-second']];ob_start();\TNL\UI\Conversation::render($simultaneous,false);$same=ob_get_clean();chatCheck(strpos($same,'newer-same-second')<strpos($same,'older-same-second'),'messages in same second use descending sequence');
